28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	#define BK7258_IRQTEST_TIMER_ID          TIMER_ID1
33	#define BK7258_IRQTEST_SOURCE            INT_SRC_TIMER
34	#define BK7258_IRQTEST_PERIOD_MS         50u
35	#define BK7258_IRQTEST_WAIT_STEP_US      10000u
36	#define BK7258_IRQTEST_WAIT_STEPS        50u
37	#define BK7258_IRQTEST_SILENCE_US        \
38	  (BK7258_IRQTEST_PERIOD_MS * 3u * 1000u)
39	#define BK7258_IRQTEST_STATUS_MASK       (1u << TIMER_ID1)
40	#define BK7258_IRQTEST_ALL_TIMERS_MASK   ((1u << TIMER_ID_MAX) - 1u)
41	
42	/****************************************************************************
43	 * Compile-time Invariants
44	 ****************************************************************************/
45	
46	_Static_assert(TIMER_ID1 == 1,
47	               "Stage B timer test requires TIMER_ID1 to remain channel 1");
48	_Static_assert(TIMER_ID_MAX == 6,
49	               "Stage B timer test requires six SDK timer channels");
50	_Static_assert(INT_SRC_TIMER == 3,
51	               "Stage B timer test requires INT_SRC_TIMER to remain source 3");
52	_Static_assert((CONFIG_TIMER_SUPPORT_ID_BITS &
53	                BK7258_IRQTEST_STATUS_MASK) != 0,
54	               "Stage B timer test requires SDK support for TIMER_ID1");
