56	/****************************************************************************
57	 * Private Data
58	 ****************************************************************************/
59	
60	static bool g_bk7258_irqtest_running;
61	static volatile uint32_t g_bk7258_irqtest_a_count;
62	static volatile uint32_t g_bk7258_irqtest_a_status;
63	static volatile uint32_t g_bk7258_irqtest_b_count;
64	static volatile uint32_t g_bk7258_irqtest_b_status;
65	
66	/****************************************************************************
67	 * Private Functions
68	 ****************************************************************************/
69	
70	/* The pinned SDK exports this helper from timer_driver.c but does not declare
71	 * it in the public timer header.  It returns and clears the six-channel raw
72	 * interrupt-status bitmap.
73	 */
74	
75	extern uint32_t timer_clear_isr_status(void);
76	
77	static bool bk7258_irqtest_claim(void)
78	{
79	  irqstate_t flags;
80	  bool claimed;
81	
82	  flags = enter_critical_section();
83	  claimed = !g_bk7258_irqtest_running;
84	  if (claimed)
85	    {
86	      g_bk7258_irqtest_running = true;
87	    }
88	
89	  leave_critical_section(flags);
90	  return claimed;
91	}
92	
93	static void bk7258_irqtest_release(void)
94	{
95	  irqstate_t flags;
96	
97	  flags = enter_critical_section();
98	  g_bk7258_irqtest_running = false;
99	  leave_critical_section(flags);
100	}
101	
102	static bool
103	bk7258_irqtest_wait(volatile uint32_t *counter)
104	{
105	  unsigned int step;
106	
107	  for (step = 0; step < BK7258_IRQTEST_WAIT_STEPS; step++)
108	    {
109	      if (*counter != 0)
110	        {
111	          return true;
112	        }
113	
114	      usleep(BK7258_IRQTEST_WAIT_STEP_US);
115	    }
116	
117	  return false;
118	}
119	
120	static void bk7258_irqtest_callback_a(void)
121	{
122	  uint32_t status = timer_clear_isr_status();
123	
124	  g_bk7258_irqtest_a_status |= status;
125	  if ((status & BK7258_IRQTEST_STATUS_MASK) != 0)
126	    {
127	      g_bk7258_irqtest_a_count++;
128	    }
129	}
130	
131	static void bk7258_irqtest_callback_b(void)
132	{
133	  uint32_t status = timer_clear_isr_status();
134	
135	  g_bk7258_irqtest_b_status |= status;
136	  if ((status & BK7258_IRQTEST_STATUS_MASK) != 0)
137	    {
138	      g_bk7258_irqtest_b_count++;
139	    }
140	}
