142	/****************************************************************************
143	 * Public Functions
144	 ****************************************************************************/
145	
146	int bk7258_sdk_irq_timer_test(void)
147	{
148	  int_group_isr_t saved_handler = NULL;
149	  const char *phase = "claim";
150	  uint32_t silence_a;
151	  uint32_t silence_b;
152	  uint32_t silence_status;
153	  uint32_t enabled;
154	  bk_err_t restore_ret;
155	  bk_err_t ret;
156	  bool restore_needed = false;
157	  bool timer_touched = false;
158	  int result = -1;
159	
160	  if (!bk7258_irqtest_claim())
161	    {
162	      printf("bkirqtest: FAIL busy\n");
163	      return -1;
164	    }
165	
166	  printf("bkirqtest: BEGIN timer=%u source=%u irq=%u period=%ums\n",
167	         (unsigned int)BK7258_IRQTEST_TIMER_ID,
168	         (unsigned int)BK7258_IRQTEST_SOURCE,
169	         (unsigned int)(BK7258_IRQ_FIRST + BK7258_IRQTEST_SOURCE),
170	         (unsigned int)BK7258_IRQTEST_PERIOD_MS);
171	
172	  phase = "snapshot";
173	  ret = bk7258_sdk_irq_test_snapshot_handler(BK7258_IRQTEST_SOURCE,
174	                                              &saved_handler);
175	  if (ret != BK_OK || saved_handler == NULL)
176	    {
177	      printf("bkirqtest: snapshot ret=%d handler=0x%08lx\n",
178	             (int)ret, (unsigned long)(uintptr_t)saved_handler);
179	      goto out;
180	    }
181	
182	  phase = "idle-guard";
183	  enabled = bk_timer_get_enable_status();
184	  if (enabled == (uint32_t)BK_ERR_TIMER_NOT_INIT)
185	    {
186	      printf("bkirqtest: timer driver is not initialized\n");
187	      goto out;
188	    }
189	
190	  if ((enabled & BK7258_IRQTEST_ALL_TIMERS_MASK) != 0)
191	    {
192	      printf("bkirqtest: timers busy enable=0x%08lx\n",
193	             (unsigned long)enabled);
194	      goto out;
195	    }
196	
197	  timer_touched = true;
198	  ret = bk_timer_stop(BK7258_IRQTEST_TIMER_ID);
199	  if (ret != BK_OK)
200	    {
201	      phase = "initial-stop";
202	      goto out;
203	    }
204	
205	  timer_clear_isr_status();
206	  g_bk7258_irqtest_a_count = 0;
207	  g_bk7258_irqtest_a_status = 0;
208	  g_bk7258_irqtest_b_count = 0;
209	  g_bk7258_irqtest_b_status = 0;
210	
211	  phase = "register-a";
212	  restore_needed = true;
213	  ret = bk_int_isr_register(BK7258_IRQTEST_SOURCE,
214	                            bk7258_irqtest_callback_a, NULL);
215	  if (ret != BK_OK)
216	    {
217	      goto out;
218	    }
219	
220	  phase = "trigger-a";
221	  ret = bk_timer_start_without_callback(BK7258_IRQTEST_TIMER_ID,
222	                                         BK7258_IRQTEST_PERIOD_MS);
223	  if (ret != BK_OK ||
224	      !bk7258_irqtest_wait(&g_bk7258_irqtest_a_count))
225	    {
226	      goto out;
227	    }
228	
229	  ret = bk_timer_stop(BK7258_IRQTEST_TIMER_ID);
230	  timer_clear_isr_status();
231	  if (ret != BK_OK || g_bk7258_irqtest_a_count == 0 ||
232	      (g_bk7258_irqtest_a_status & BK7258_IRQTEST_STATUS_MASK) == 0)
233	    {
234	      goto out;
235	    }
236	
237	  printf("bkirqtest: A count=%lu status=0x%08lx\n",
238	         (unsigned long)g_bk7258_irqtest_a_count,
239	         (unsigned long)g_bk7258_irqtest_a_status);
240	
241	  silence_a = g_bk7258_irqtest_a_count;
242	  silence_b = g_bk7258_irqtest_b_count;
243	
244	  phase = "unregister";
245	  ret = bk_int_isr_unregister(BK7258_IRQTEST_SOURCE);
246	  if (ret != BK_OK)
247	    {
248	      goto out;
249	    }
250	
251	  phase = "silence-trigger";
252	  ret = bk_timer_start_without_callback(BK7258_IRQTEST_TIMER_ID,
253	                                         BK7258_IRQTEST_PERIOD_MS);
254	  if (ret != BK_OK)
255	    {
256	      goto out;
257	    }
258	
259	  usleep(BK7258_IRQTEST_SILENCE_US);
260	  silence_status = timer_clear_isr_status();
261	  ret = bk_timer_stop(BK7258_IRQTEST_TIMER_ID);
262	  timer_clear_isr_status();
263	  if (ret != BK_OK ||
264	      (silence_status & BK7258_IRQTEST_STATUS_MASK) == 0 ||
265	      g_bk7258_irqtest_a_count != silence_a ||
266	      g_bk7258_irqtest_b_count != silence_b)
267	    {
268	      goto out;
269	    }
270	
271	  printf("bkirqtest: SILENT a=%lu b=%lu status=0x%08lx\n",
272	         (unsigned long)g_bk7258_irqtest_a_count,
273	         (unsigned long)g_bk7258_irqtest_b_count,
274	         (unsigned long)silence_status);
275	
276	  phase = "register-b";
277	  ret = bk_int_isr_register(BK7258_IRQTEST_SOURCE,
278	                            bk7258_irqtest_callback_b, NULL);
279	  if (ret != BK_OK)
280	    {
281	      goto out;
282	    }
283	
284	  phase = "trigger-b";
285	  ret = bk_timer_start_without_callback(BK7258_IRQTEST_TIMER_ID,
286	                                         BK7258_IRQTEST_PERIOD_MS);
287	  if (ret != BK_OK ||
288	      !bk7258_irqtest_wait(&g_bk7258_irqtest_b_count))
289	    {
290	      goto out;
291	    }
292	
293	  ret = bk_timer_stop(BK7258_IRQTEST_TIMER_ID);
294	  timer_clear_isr_status();
295	  if (ret != BK_OK || g_bk7258_irqtest_b_count == 0 ||
296	      (g_bk7258_irqtest_b_status & BK7258_IRQTEST_STATUS_MASK) == 0 ||
297	      g_bk7258_irqtest_a_count != silence_a)
298	    {
299	      goto out;
300	    }
301	
302	  printf("bkirqtest: B count=%lu status=0x%08lx\n",
303	         (unsigned long)g_bk7258_irqtest_b_count,
304	         (unsigned long)g_bk7258_irqtest_b_status);
305	  result = 0;
306	
307	out:
308	  if (timer_touched)
309	    {
310	      bk_timer_stop(BK7258_IRQTEST_TIMER_ID);
311	      timer_clear_isr_status();
312	    }
313	
314	  if (restore_needed)
315	    {
316	      restore_ret = bk_int_isr_register(BK7258_IRQTEST_SOURCE,
317	                                        saved_handler, NULL);
318	      if (restore_ret != BK_OK)
319	        {
320	          printf("bkirqtest: restore FAIL ret=%d\n", (int)restore_ret);
321	          phase = "restore";
322	          result = -1;
323	        }
324	      else
325	        {
326	          printf("bkirqtest: restore OK\n");
327	        }
328	    }
329	
330	  if (result == 0)
331	    {
332	      printf("bkirqtest: PASS\n");
333	    }
334	  else
335	    {
336	      printf("bkirqtest: FAIL phase=%s\n", phase);
337	    }
338	
339	  bk7258_irqtest_release();
340	  return result;
341	}
